    /// The transcribed table for a palette, or `nil` if it is not one of these.
    public static func table(
        for palette: PseudoColorPalette
    ) -> [(red: UInt8, green: UInt8, blue: UInt8)]? {
        let packed: [UInt32]
        switch palette {
        case .viridis: packed = viridisPacked
        case .inferno: packed = infernoPacked
        case .magma: packed = magmaPacked
        case .plasma: packed = plasmaPacked
        default: return nil
        }
        return packed.map {
            (red: UInt8(($0 >> 16) & 0xFF),
             green: UInt8(($0 >> 8) & 0xFF),
             blue: UInt8($0 & 0xFF))
        }
    }

